              body: "위 목록은 고용보험법 시행규칙 제87조 제2항과 「실업인정 및 재취업지원규정」 제10조 제5항이 정한 것이고, 여기에 해당하면 근로의 의사와 능력을 가지고 적극적인 재취업활동을 하지 않은 것으로 보아 실업이 인정되지 않아요.\n\n첫 항목의 세 가지는 성격이 다릅니다. 게을러서가 아니라 **지금 일할 수 있는 상태가 아니어서** 인정되지 않는 경우예요. 이때는 무리해서 구직활동을 만들기보다 고용센터에 수급기간 연기를 신청해 두고 가능해진 뒤에 받는 편이 낫습니다.",
