          body: "**워크넷 이메일 입사지원의 상한을 모르고 낭패를 보는 경우가 많아요.** 온라인으로 편하게 지원할 수 있으니 그것만 반복하기 쉬운데, 소정급여일수 120일 이하 수급자가 4회 이상, 150일 이상 수급자가 6회 이상 하면 인정되지 않아요. 인정받을 수 있는 것은 각각 3회, 5회까지입니다. 고용센터가 지시해서 지원한 건은 이 횟수에 들어가지 않아요.\n\n한 가지 더 있습니다. **반복수급자와 장기수급자는 재취업활동 인정 기준이 일반 수급자보다 강화돼서 적용돼요.** 본인이 여기에 해당하는지, 어떤 기준이 적용되는지는 담당자에게 확인하세요.\n\n구직활동 때문에 실업인정일에 못 나가는 일도 생겨요. **고용센터가 소개한 구인자와의 면접**이나 **고용센터가 지시한 직업능력개발 훈련** 때문에 출석할 수 없었다면, 출석할 수 없었던 사유를 적은 증명서를 제출해 실업의 인정을 받을 수 있습니다. 질병·부상으로 계속하여 7일 미만 출석하지 못한 경우와 천재지변 등 부득이한 사유도 같아요.",
