          body: "실업 상태였던 날이라도 **실업의 인정을 받지 못하면 그 날은 지급되지 않아요.** 구직급여는 인정을 받은 날에 대해서만 나옵니다.\n\n실업인정일에 출석하지 못했다고 그 기간이 바로 사라지는 것은 아니에요. **출석할 수 없었던 사유를 적은 증명서를 제출하면 실업의 인정을 받을 수 있는 경우**가 법에 있습니다. 질병이나 부상으로 출석할 수 없었고 그 기간이 계속하여 7일 미만인 경우, 고용센터가 소개한 구인자와의 면접 때문인 경우, 고용센터가 지시한 직업능력개발 훈련을 받느라 못 간 경우, 천재지변이나 그 밖의 부득이한 사유가 있는 경우예요. 재취업활동이 인정되지 않아 부지급 처리되면 그 회차는 들어오지 않아요.\n\n입금이 늦어질 때 확인할 것은 두 가지입니다. 실업인정 신청이 정상 처리됐는지, 그리고 계좌 정보가 맞는지예요. 시행령은 **직업안정기관의 장이 실업을 인정한 경우 그 사실을 수급자격증에 적어 반환하도록** 정하고 있으니, 인정 여부는 수급자격증에서도 확인할 수 있어요. 실업인정 신청 자체는 특정 회차를 제외하면 방문 없이 온라인으로 할 수 있습니다.",
