          body: "시간이 곧 선택지예요. **이직확인서가 처리되기 전에 움직이는 쪽이 훨씬 간단합니다.** 처리된 뒤에는 정정과 사실관계 확인이 함께 걸려 오래 걸려요.\n\n그리고 사실과 다르게 신고하는 쪽으로는 가지 마세요. 실업급여 신청 시 작성 내용이 사실과 다르면 부정수급이 되어 추가징수 등 불이익이 생기고, 1년 이하의 징역 또는 300만원 이하의 벌금형까지 받을 수 있어요. 실제로 권고를 받고 나온 것이라면 그 경위를 있는 그대로 설명하고 자료로 보이는 것이 맞습니다.",
          cta: { label: "이직확인서 처리현황 조회하기", url: "https://www.work24.go.kr/ei/a/b/1200/openHPEIAB1200M01.do", org: "고용노동부 고용24", note: "퇴직 사유가 어떻게 적혔는지, 아직 처리 전인지부터 확인해요" },
