          answer: "고용노동부 노동포털에서 진정서를 온라인으로 낼 수 있어요. 수수료는 없고 처리기간은 25일입니다.",
          widgets: [
            {
              type: "stepbar",
              steps: [
                { tab: "진정서 접수", title: "노동포털에서 진정서를 냅니다", body: "'진정서(체불, 직장 내 괴롭힘, 기타 노동법 위반)' 하나로 체불·직장 내 괴롭힘·그 밖의 노동법 위반을 함께 접수해요. 신청 자격은 근로자(개인회원)이고, 방문·우편·인터넷으로 낼 수 있습니다. 근무한 사업장 소재지의 관할 지방관서 고객지원실에 직접 방문해도 돼요.", prep: "3번의 증빙자료", time: "수수료 없음", action: { label: "임금체불 진정서 접수하기", url: "https://labor.moel.go.kr/minwonApply/minwonFormat.do?searchVal=SN001" } },
                { tab: "감독관 조사", title: "담당 근로감독관이 배정돼 조사해요", body: "근로감독관이 신고인과 피신고인에게 출석을 요구해 조사를 진행합니다. 조사 과정에서 신고인에게 연락이 올 수 있고, 각 진행 단계마다 알림톡이나 문자로 통보돼요. 처리기간은 25일입니다.", prep: "출석 요구에 응할 준비", time: "처리기간 25일" },
                { tab: "시정지시", title: "법 위반이 확인되면 사업주에게 시정지시가 나가요", body: "근로감독관의 조사로 임금체불 등 법 위반 사실이 확인되면 사업주에게 시정지시를 하고, 법 위반이 시정되면 사건을 종결합니다.", prep: "없음", time: "조사 후" },
                { tab: "형사입건", title: "시정하지 않으면 형사입건으로 넘어가요", body: "시정지시를 이행하지 않으면 형사입건 후 수사에 착수해 검찰에 송치합니다. 임금체불 사업주는 3년 이하의 징역 또는 3,000만원 이하의 벌금형에 처해져요.", prep: "없음", time: "시정지시 미이행 시" },
              ],
            },
          ],
          body: "진정과 고소는 다릅니다. **진정**은 사업주가 체불임금을 청산하도록 고용노동부에 요구하는 것이고, **고소**는 근로기준법 등 위반에 대한 처벌을 요청하는 것이에요. 진정은 노동포털에서 온라인으로 낼 수 있지만, 고소는 근무한 사업장 소재지의 관할 지방관서 고객지원실을 직접 방문해야 합니다.\n\n**만 24세 이하라면** 청소년 근로권익센터를 통해 공인노무사가 상담하고 진정사건을 대리하는 지원을 받을 수 있어요. 혼자 진행하기 부담스러울 때 먼저 알아볼 곳입니다.\n\n실업급여 신청과 진정은 서로 미룰 이유가 없어요. 실업급여는 마지막 근무일 다음 날부터 1년 안에서만 받을 수 있으니, 진정 결과를 기다리며 미루지 말고 고용센터에 먼저 수급자격 인정을 신청하세요.",
          cta: { label: "임금체불 진정서 접수하기", url: "https://labor.moel.go.kr/minwonApply/minwonFormat.do?searchVal=SN001", org: "고용노동부 노동포털", note: "신청 자격 근로자(개인회원) · 처리기간 25일 · 수수료 없음 · 지방고용노동관서 접수" },
          quote: { law: "고용노동부 노동포털 — 처리절차", text: "\"① 담당 근로감독관이 배정되면 근로감독관이 신고인과 피신고인에게 출석을 요구하여 조사 진행 ② 근로감독관의 조사로 임금체불 등 법 위반 사실이 확인되는 경우 사업주에게 시정지시 → 법 위반이 시정되면 사건을 종결 ③ 시정지시 미이행시 형사입건 후 수사를 착수하여 검찰에 송치 - 임금체불 사업주는 3년 이하의 징역 또는 3,000만원 이하의 벌금형에 처함\"" },
