          body: "가장 효율이 좋은 것은 **고용센터가 지시한 직업지도 프로그램**이에요. 한 번 참여로 2회의 재취업활동이 되니까요. 다만 8시간 미만이면 1회로 셉니다.\n\n훈련을 듣고 있다면 매번 구직활동을 따로 만들지 않아도 되지만, **수강증명서를 4주에 한 번 내는 일은 잊지 마세요.** 이 서류가 없으면 훈련을 받고 있어도 인정 절차가 진행되지 않아요.\n\n참여를 권유받았을 때 가볍게 넘기지 않는 편이 좋습니다. 법은 직업안정기관의 장이 실업을 인정할 때 **재취업 활동에 관한 계획의 수립 지원과 직업소개 등의 조치를 하여야 한다**고 정하면서, 수급자격자는 정당한 사유가 없으면 그 조치에 따라야 한다고 함께 적어 두었어요.",
          cta: { label: "실업인정 온라인 신청하기", url: "https://www.work24.go.kr/ei/a/h/1200/openHPEIAH1200M02.do", org: "고용노동부 고용24", note: "참여한 교육·훈련 내용을 실업인정 신청서에 적어 제출해요" },
          quote: { law: "고용보험법 시행규칙 제87조 제1항 · 「실업인정 및 재취업지원규정」 제10조", text: "\"영 제63조제3항에 따라 다음 각 호의 어느 하나에 해당하는 경우에 적극적인 재취업활동을 한 것으로 본다. … 3. 직업능력개발 훈련 등을 받는 경우 중 고용노동부장관이 정한 경우 4. 직업안정기관에서 실시하는 직업지도 프로그램에 참여한 경우\" · \"고용센터에서 실시하는 성취프로그램 등 직업지도 및 재취업지원 프로그램 참여 지시에 응한 경우에는 2회의 재취업활동을 한 것으로 봄(다만, 8시간 미만의 직업지도등에 참여한 경우에는 1회의 재취업활동을 한것으로 봄)\"" },
