          body: "여기서 갈리는 것은 **\"정당한 사유가 있었는가\"**예요. 무조건 다 받아야 하는 것은 아닙니다. 소개받은 일자리의 임금이 같은 지역·같은 업무의 통상 임금보다 100분의 20 이상 낮은 경우처럼, 고용노동부장관이 정한 기준에 해당하면 거부해도 정지되지 않아요.\n\n반대로 **연락 없이 안 나가는 것이 가장 나쁜 선택**입니다. 미리 지정된 출석일에 정당한 사유 없이 나가지 않으면 그 기간은 재취업활동을 하지 않은 것으로 보아 실업이 인정되지 않아요. 사정이 생기면 먼저 담당자에게 알리세요.\n\n못 나갈 사정이 있을 때 쓰는 길도 법에 있습니다. **출석할 수 없었던 사유를 적은 증명서를 내면 실업의 인정을 받을 수 있어요.** 질병이나 부상으로 출석할 수 없었고 그 기간이 계속하여 7일 미만인 경우, 고용센터가 소개한 구인자와의 면접 때문에 못 간 경우, **지시받은 훈련을 받느라 못 간 경우**, 천재지변이나 그 밖의 부득이한 사유가 여기에 해당합니다.",
