          body: "여기서 흔한 착각이 하나 있어요. **\"증빙 서류 목록\"이 따로 정해져 있는 것이 아닙니다.** 별표 2는 사유마다 판단 기준을 문장으로 적어 두었고, 그 기준에 맞는다는 것을 보여주는 자료가 곧 증빙이에요.\n\n그래서 준비는 목록을 찾는 일이 아니라 **기준을 읽고 그 기준에 대응하는 자료를 고르는 일**입니다. \"1년 이내 2개월 이상\"이 기준이면 언제부터 언제까지 어긋났는지가 드러나는 자료, \"왕복 3시간 이상\"이 기준이면 이전 전후의 통근 시간을 보여주는 자료, \"30일 이상 간호\"가 기준이면 그 기간과 관계를 보여주는 자료예요.\n\n조문이 직접 자료를 지정한 곳도 있습니다. 본인 건강을 이유로 한 이직은 **의사의 소견서와 사업주 의견 등에 근거해 객관적으로 인정**되어야 한다고 별표 2가 명시하고 있어요.",
