          body: "회사가 \"징계해고\"라고 이름 붙였다고 자동으로 못 받는 것이 아닙니다. **법이 보는 것은 이름이 아니라 세 가지 사유에 해당하는지**예요.\n\n특히 나목은 회사 주장만으로 정해지지 않아요. 사업에 막대한 지장을 초래했거나 재산상 손해를 끼쳤는지는 **고용노동부령이 정한 기준(시행규칙 별표 1의2)** 에 맞는지로 봅니다.\n\n판단 주체도 회사가 아니라 **직업안정기관의 장**이에요. 회사가 적어 낸 사유와 실제가 다르다면 그 경위를 보여주는 자료를 준비해 고용센터에 설명하세요.\n\n반대 방향도 알아 두세요. 징계 사유가 있는데 회사가 해고 대신 사직을 권해서 나갔다면, **중대한 귀책사유가 있는 사람이 해고되지 않고 사업주의 권고로 이직한 경우**로 보아 마찬가지로 제한됩니다. 이름을 권고사직으로 바꾼다고 결과가 달라지지 않아요.",
