          body: "기한이 짧습니다. **부당해고등이 있었던 날부터 3개월**이에요. 실업급여의 1년과 헷갈리기 쉬우니 따로 세어 두세요.\n\n무엇이 부당해고등인지도 법이 정해 두었어요. 사용자가 근로자에게 **정당한 이유 없이 해고, 휴직, 정직, 전직, 감봉, 그 밖의 징벌**을 하는 것입니다. 정당한 이유 없이 이런 일을 당한 근로자는 관할 지방노동위원회에 구제신청을 할 수 있어요.\n\n서면 통지가 없었다면 절차 위반을 넘어 **해고 자체가 효력이 없다**고 다툴 수 있어요. 근로기준법은 해고를 서면으로 통지하여야 효력이 있다고 정하고 있습니다.\n\n해고 자체가 금지되는 기간도 있습니다. 업무상 부상이나 질병의 요양을 위해 휴업한 기간과 **그 후 30일**, 산전·산후 여성이 휴업한 기간과 **그 후 30일**에는 해고하지 못해요. 다만 사용자가 근로기준법 제84조에 따라 일시보상을 하였거나 사업을 계속할 수 없게 된 경우는 예외입니다.\n\n구제신청을 한다고 실업급여를 못 받는 것은 아닙니다. **둘은 별개 절차예요.** 실업급여는 1년 기한이 있으니 먼저 신청해 두세요.",
