          body: "먼저 대상부터 봅니다. 조문은 수급자격자를 대상으로 하면서 **「외국인근로자의 고용 등에 관한 법률」 제2조에 따른 외국인 근로자는 제외**한다고 적고 있어요.\n\n이 수당은 **빨리 취업한 것에 대한 보상**이 아니라 **빨리 취업해서 오래 일한 것**에 대한 보상이에요. 그래서 조건이 두 겹입니다.\n\n앞쪽 조건은 재취업 시점입니다. 실업 신고일부터 14일이 지난 후 재취업했고, **재취업한 날의 전날을 기준으로** 소정급여일수를 2분의 1 이상 남겼어야 해요.\n\n뒤쪽 조건은 재취업 이후입니다. 그 일자리에서 **12개월 이상 계속 고용**되었거나 12개월 이상 계속 사업을 영위했어야 합니다. 그래서 청구도 12개월이 지난 뒤에 하게 돼 있어요.",
