          body: "정리하면 **신고는 2개월, 급여는 전날까지**입니다.\n\n취업 사실을 늦게 알리거나 알리지 않으면 그 사이에 나간 급여가 문제가 됩니다. 취업일이 확인되는 자료를 첨부해 신고하면 취업 전날까지의 구직급여는 정상적으로 받아요.\n\n조기재취업수당은 이것과 **별개 절차**입니다. 취업사실 신고는 2개월 이내에, 조기재취업수당 청구는 재취직일부터 12개월이 지난 뒤에 합니다.",
