          body: "취업으로 인정되는 기준(2번 표)에 못 미치는 짧은 일이라도 **근로사실 신고는 별개로 해야 합니다.** 신고하면 그 기간이 지급되지 않는 선에서 정리되지만, 신고하지 않으면 부정수급이 됩니다.\n\n특히 일용직은 적발 사례가 많습니다. **사업주가 세금 신고를 하면서 국세청에 일용근로자의 소득을 신고**하는 과정에서 드러나는 경우가 많다고 안내하고 있어요. 하루치라도 신고하는 편이 안전합니다.",
