          body: "일용직이라고 못 받는 것이 아닙니다. **상용직과 같은 요건에 하나가 더 붙을 뿐**이에요.\n\n18개월이 짧아 보인다면 **기준기간 연장**을 먼저 보세요. 이직일 이전 18개월 동안 질병·부상 등으로 계속하여 30일 이상 보수를 받을 수 없었던 기간이 있으면, 그 일수만큼 18개월이 늘어납니다(3년 한도). 일이 끊기거나 아파서 쉰 기간이 길었다면 이 조항으로 180일이 채워질 수 있어요.\n\n더 붙는 것이 **근로일수 요건**입니다. 신청일이 속한 달의 직전 달 초일부터 신청일까지 세어, 그 기간에 일한 날이 전체 일수의 3분의 1 미만이어야 해요. \"최근에 일이 거의 없었다\"를 숫자로 확인하는 장치입니다.\n\n용어도 짚어 둘게요. 여기서 **일용근로자는 1개월 미만 동안 고용되는 사람**을 말합니다. 하루 단위로 일한다고 해서 모두가 아니라, 고용 기간이 1개월 미만인 경우예요.",
