          body: "건설일용의 차이는 두 가지인데, **대기기간 쪽이 더 큽니다.**\n\n일반적으로는 실업 신고일부터 7일간을 대기기간으로 보아 구직급여를 지급하지 않아요. 그런데 **최종 이직 당시 건설일용근로자였던 사람에 대해서는 실업의 신고일부터 계산해 지급**합니다. 대기기간 없이 그 7일분도 지급된다는 뜻이에요.\n\n근로일수 요건도 선택지가 하나 더 있습니다. 3분의 1 계산이 애매하더라도 **신청일 이전 14일간 연속으로 근로내역이 없으면** 그것으로 갈 수 있어요. 조문이 가목과 나목을 \"다음 각 목의 어느 하나에 해당할 것\"으로 묶어 두었기 때문입니다.",
