          quote: { law: "고용보험법 제15조 제1항 [시행 2026. 8. 20.]", text: "\"사업주는 그 사업에 고용된 근로자의 피보험자격의 취득 및 상실 등에 관한 사항을 대통령령으로 정하는 바에 따라 고용노동부장관에게 신고하여야 한다.\"" },
